#!/bin/bash

# Set the start and end dates for the release notes
START_DATE="2023-02-01"
END_DATE="2023-02-17"

# Get the current date
CURRENT_DATE=$(date "+%Y-%m-%d")

# Get the latest tag version
LATEST_TAG=$(git describe --tags --abbrev=0)

# Create the release notes file
RELEASE_NOTES_FILE="release\_notes\_${LATEST\_TAG}.md"

# Add the release information to the release notes file
echo "# Release ${LATEST\_TAG} - ${CURRENT\_DATE}" > ${RELEASE\_NOTES\_FILE}
echo "-------------------------" >> ${RELEASE\_NOTES\_FILE}
git log ${LATEST\_TAG}..HEAD --pretty=format:"\* %s" >> ${RELEASE\_NOTES\_FILE}

# Add the commits between the start and end dates to the release notes file
echo "" >> ${RELEASE\_NOTES\_FILE}
echo "## Changes since ${START\_DATE}" >> ${RELEASE\_NOTES\_FILE}
echo "-------------------------" >> ${RELEASE\_NOTES\_FILE}
git log --pretty=format:"\* %s" --after=${START\_DATE} --before=${END\_DATE} >> ${RELEASE\_NOTES\_FILE}

# Open the release notes file for editing
$EDITOR ${RELEASE\_NOTES\_FILE}

# Export the release notes as a Markdown file
pandoc ${RELEASE\_NOTES\_FILE} -s -o release_notes_${LATEST\_TAG}.pdf
